def pbSwitchInBetween(_idxBattler, _checkLaxOnly = false, _canCancel = false)
  ret = @switches[@switchindex]
  @switchindex += 1
  return ret
end

def pbRandom(_num)
  ret = @randomnums[@randomindex]
  @randomindex += 1
  return ret
end

def pbClearChoice(idxBattler)
  @choices[idxBattler] = [] if !@choices[idxBattler]
  @choices[idxBattler][0] = :None
  @choices[idxBattler][1] = 0
  @choices[idxBattler][2] = nil
  @choices[idxBattler][3] = -1
end

def pbCancelChoice(idxBattler)
  # If idxBattler's choice was to use an item, return that item to the Bag
  if @choices[idxBattler][0] == :UseItem
    item = @choices[idxBattler][1]
    pbReturnUnusedItemToBag(item, idxBattler) if item
  end
  # If idxBattler chose to Mega Evolve, cancel it
  pbUnregisterMegaEvolution(idxBattler)
  # Clear idxBattler's choice
  pbClearChoice(idxBattler)
end

def pbCommandPhase
  @command_phase = true
  @scene.pbBeginCommandPhase
  # Reset choices if commands can be shown
  @battlers.each_with_index do |b, i|
    next if !b
    pbClearChoice(i) if pbCanShowCommands?(i)
  end
  # Reset choices to perform Mega Evolution if it wasn't done somehow
  2.times do |side|
    @megaEvolution[side].each_with_index do |megaEvo, i|
      @megaEvolution[side][i] = -1 if megaEvo >= 0
    end
  end
  # Choose actions for the round (player first, then AI)
  pbCommandPhaseLoop(true)    # Player chooses their actions
  if @decision != 0   # Battle ended, stop choosing actions
    @command_phase = false
    return
  end
  pbCommandPhaseLoop(false)   # AI chooses their actions
  @command_phase = false
end

def pbRemoveItem(permanent = true)
  @effects[PBEffects::ChoiceBand] = nil if !hasActiveAbility?(:GORILLATACTICS)
  @effects[PBEffects::Unburden]   = true if self.item && hasActiveAbility?(:UNBURDEN)
  setInitialItem(nil) if permanent && self.item == self.initialItem
  self.item = nil
end

def pbConsumeItem(recoverable = true, symbiosis = true, belch = true)
  PBDebug.log("[Item consumed] #{pbThis} consumed its held #{itemName}")
  if recoverable
    setRecycleItem(@item_id)
    @effects[PBEffects::PickupItem] = @item_id
    @effects[PBEffects::PickupUse]  = @battle.nextPickupUse
  end
  setBelched if belch && self.item.is_berry?
  pbRemoveItem
  pbSymbiosis if symbiosis
end

def pbItemOnStatDropped(move_user = nil)
  return false if !@statsDropped
  return false if !itemActive?
  return Battle::ItemEffects.triggerOnStatLoss(self.item, self, move_user, @battle)
end

def item
  return GameData::Item.try_get(@item_id)
end

def item=(value)
  new_item = GameData::Item.try_get(value)
  @item_id = (new_item) ? new_item.id : nil
  @pokemon.item = @item_id if @pokemon
end

class HandlerHashSymbol
  def initialize
    @hash    = {}
    @add_ifs = {}
  end

  def [](sym)
    sym = sym.id if !sym.is_a?(Symbol) && sym.respond_to?("id")
    return @hash[sym] if sym && @hash[sym]
    @add_ifs.each_value do |add_if|
      return add_if[1] if add_if[0].call(sym)
    end
    return nil
  end

  def add(sym, handler = nil, &handlerBlock)
    if ![Proc, Hash].include?(handler.class) && !block_given?
      raise ArgumentError, "#{self.class.name} for #{sym.inspect} has no valid handler (#{handler.inspect} was given)"
    end
    @hash[sym] = handler || handlerBlock if sym
  end

  def addIf(sym, conditionProc, handler = nil, &handlerBlock)
    if ![Proc, Hash].include?(handler.class) && !block_given?
      raise ArgumentError, "addIf call for #{sym} in #{self.class.name} has no valid handler (#{handler.inspect} was given)"
    end
    @add_ifs[sym] = [conditionProc, handler || handlerBlock]
  end

  def copy(src, *dests)
    handler = self[src]
    return if !handler
    dests.each { |dest| add(dest, handler) }
  end

  def remove(key)
    @hash.delete(key)
  end

  def clear
    @hash.clear
    @add_ifs.clear
  end

  def trigger(sym, *args)
    sym = sym.id if !sym.is_a?(Symbol) && sym.respond_to?("id")
    handler = self[sym]
    return handler&.call(sym, *args)
  end
end

def self.triggerOnStatLoss(item, user, move_user, battle)
  return trigger(OnStatLoss, item, user, move_user, battle)
end

def initialize(scene, p1, p2, player, opponent)
  if p1.length == 0
    raise ArgumentError.new(_INTL("Party 1 has no Pokémon."))
  elsif p2.length == 0
    raise ArgumentError.new(_INTL("Party 2 has no Pokémon."))
  end
  @scene             = scene
  @peer              = Peer.new
  @field             = ActiveField.new    # Whole field (gravity/rooms)
  @sides             = [ActiveSide.new,   # Player's side
                        ActiveSide.new]   # Foe's side
  @positions         = []                 # Battler positions
  @battlers          = []
  @sideSizes         = [1, 1]   # Single battle, 1v1
  @backdrop          = ""
  @backdropBase      = nil
  @time              = 0
  @environment       = :None   # e.g. Tall grass, cave, still water
  @turnCount         = 0
  @decision          = 0
  @caughtPokemon     = []
  player   = [player] if !player.nil? && !player.is_a?(Array)
  opponent = [opponent] if !opponent.nil? && !opponent.is_a?(Array)
  @player            = player     # Array of Player/NPCTrainer objects, or nil
  @opponent          = opponent   # Array of NPCTrainer objects, or nil
  @items             = nil
  @ally_items        = nil        # Array of items held by ally. This is just used for Mega Evolution for now.
  @party1            = p1
  @party2            = p2
  @party1order       = Array.new(@party1.length) { |i| i }
  @party2order       = Array.new(@party2.length) { |i| i }
  @party1starts      = [0]
  @party2starts      = [0]
  @internalBattle    = true
  @debug             = false
  @canRun            = true
  @canLose           = false
  @canSwitch         = true
  @switchStyle       = true
  @showAnims         = true
  @controlPlayer     = false
  @expGain           = true
  @moneyGain         = true
  @disablePokeBalls  = false
  @sendToBoxes       = 1
  @rules             = {}
  @priority          = []
  @priorityTrickRoom = false
  @choices           = []
  @megaEvolution     = [
    [-1] * (@player ? @player.length : 1),
    [-1] * (@opponent ? @opponent.length : 1)
  ]
  @initialItems      = [
    Array.new(@party1.length) { |i| (@party1[i]) ? @party1[i].item_id : nil },
    Array.new(@party2.length) { |i| (@party2[i]) ? @party2[i].item_id : nil }
  ]
  @recycleItems      = [Array.new(@party1.length, nil),   Array.new(@party2.length, nil)]
  @belch             = [Array.new(@party1.length, false), Array.new(@party2.length, false)]
  @battleBond        = [Array.new(@party1.length, false), Array.new(@party2.length, false)]
  @corrosiveGas      = [Array.new(@party1.length, false), Array.new(@party2.length, false)]
  @usedInBattle      = [Array.new(@party1.length, false), Array.new(@party2.length, false)]
  @successStates     = []
  @lastMoveUsed      = nil
  @lastMoveUser      = -1
  @switching         = false
  @futureSight       = false
  @command_phase     = false
  @endOfRound        = false
  @moldBreaker       = false
  @runCommand        = 0
  @nextPickupUse     = 0
  @struggle          = Move::Struggle.new(self, nil)
  @mega_rings        = []
  GameData::Item.each { |item| @mega_rings.push(item.id) if item.has_flag?("MegaRing") }
  @battleAI          = AI.new(self)
end

module GameData
  class Environment
    attr_reader :id
    attr_reader :real_name
    attr_reader :battle_base

    DATA = {}

    extend ClassMethodsSymbols
    include InstanceMethods

    def self.load; end
    def self.save; end

    def initialize(hash)
      @id          = hash[:id]
      @real_name   = hash[:name] || "Unnamed"
      @battle_base = hash[:battle_base]
    end

    # @return [String] the translated name of this environment
    def name
      return _INTL(@real_name)
    end
  end
end

