def self.isNight?(time = nil)
  time = pbGetTimeNow if !time
  return (time.hour >= 20 || time.hour < 5)
end

def self.isEvening?(time = nil)
  time = pbGetTimeNow if !time
  return (time.hour >= 17 && time.hour < 20)
end
